usage.code:
import { SwipeRow } from "solen-design/react";

const actions = [
  { id: "delete", label: "删除" },
  { id: "pin", label: "置顶" },
  { id: "mute", label: "静音", dismiss: true }
];

<SwipeRow
  actions={actions}
  direction="left"
  height={64}
  radius={16}
  actionWidth={80}
  commitAt={0.6}
  fullSwipe={true}
  onCommit={(action) => console.log("commit", action.id)}
  onOpenChange={(open) => console.log("open", open)}
>
  <strong style={{ fontWeight: 600 }}>阿达 · 陈</strong>
  <span style={{ opacity: 0.55 }}>刚转发了一份合同</span>
</SwipeRow>
